// TeamsInspector — the org-chart's detail panel for the current selection: a position's identity +
// derived communication list, or a relationship's archetype + its two directions of communication
// forms. Promoted from harvested (it was already complete and tested) into base-studio-code, refactored
// to use the real Box/Row/Stack/Text/Chip/IconBox/ColorSwatch primitives, the promoted teams-form-lane
// and ui-confirm-button components, and the real SectionLabel in place of a local BlockLabel (it
// already supports the same label + optional right-slot pattern). Also fixed a latent bug: the demo
// archetypes were missing the `blurb` field FormChip's note relies on.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Chip } from "@/shared/ui/data/Chip";
import { IconBox } from "@/shared/ui/data/IconBox";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { ConfirmButton } from "@/shared/ui/controls/ConfirmButton";
import { FormLane, type CommunicationForm } from "@/components/teams-form-lane";

export interface Position { nodeId: string; kind: "agent" | "resource" | "external"; personaId?: string; label?: string }
export interface Relationship { id: string; from: string; to: string; archetype: string }
export interface Team { positions: Position[]; relationships: Relationship[] }
export interface Persona { id: string; name: string; role?: string; blurb?: string; glyph?: string }
export interface RelationshipArchetype { id: string; label: string; hue: number; blurb?: string; forward?: CommunicationForm[]; backward?: CommunicationForm[] }
export interface Selection { type: "node" | "edge"; id: string }
function positionDisplay(pos: Position, personas: Persona[]): { glyph: string; name: string; role?: string; blurb: string; dept: string } {
  if (pos.kind === "agent") {
    const p = personas.find((pp) => pp.id === pos.personaId);
    return { glyph: p?.glyph ?? "◆", name: p?.name ?? pos.label ?? "Unassigned", role: p?.role, blurb: p?.blurb ?? "", dept: p?.role ?? "unassigned" };
  }
  return { glyph: pos.kind === "resource" ? "▤" : "○", name: pos.label ?? pos.kind, blurb: "", dept: pos.kind };
}

const PANEL = { flex: 1, minWidth: 0, borderLeft: "1px solid var(--border-soft)", overflowY: "auto" as const };
const BLOCK = { padding: "15px 17px", borderBottom: "1px solid var(--border-soft)" };
const DEMO_TEAM: Team = {
  positions: [
    { nodeId: "n1", kind: "agent", personaId: "p1" },
    { nodeId: "n2", kind: "agent", personaId: "p2" },
  ],
  relationships: [{ id: "r1", from: "n1", to: "n2", archetype: "partners" }],
};
const DEMO_PERSONAS: Persona[] = [
  { id: "p1", name: "builder-1", role: "engineer", blurb: "Implements features end to end, from the plan to a merged PR." },
  { id: "p2", name: "reviewer-2", role: "reviewer", blurb: "Reviews PRs and enforces scope." },
];
const DEMO_ARCHETYPES: RelationshipArchetype[] = [
  { id: "partners", label: "partners with", hue: 150, blurb: "Coordinates directly - shares context both ways.",
    forward: [{ id: "f1", label: "status update", color: "var(--accent)", arrow: "→", blurb: "A brief on progress, blockers, and next steps." }],
    backward: [{ id: "f2", label: "status update", color: "var(--accent)", arrow: "→", blurb: "A brief on progress, blockers, and next steps." }] },
];
export function TeamsInspector({
  org = DEMO_TEAM, personas = DEMO_PERSONAS, archetypes = DEMO_ARCHETYPES,
  sel = { type: "node", id: "n1" }, onDeletePosition, onDeleteRelationship, loading = false, error,
}: {
  org?: Team; personas?: Persona[]; archetypes?: RelationshipArchetype[]; sel?: Selection;
  onDeletePosition?: (nodeId: string) => void; onDeleteRelationship?: (relId: string) => void;
  loading?: boolean; error?: string | boolean;
}) {
  if (error) {
    return (
      <Box style={{ ...PANEL, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Text tone="danger" size={12} style={{ padding: "0 17px", textAlign: "center" }}>{typeof error === "string" ? error : "Couldn't load the selection."}</Text>
      </Box>
    );
  }
  if (loading) {
    return (
      <Box style={PANEL}>
        <Box style={{ ...BLOCK, padding: "16px 17px 14px" }}>
          <Row gap={11} align="center">
            <Skeleton w={40} h={40} radius={11} />
            <Box style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 6 }}>
              <Skeleton w="55%" h={14} />
              <Skeleton w="35%" h={10} />
            </Box>
          </Row>
        </Box>
        <Box style={BLOCK}>
          <Skeleton w="30%" h={9} style={{ marginBottom: 9 }} />
          <Skeleton h={12} style={{ marginBottom: 6 }} />
          <Skeleton w="80%" h={11} />
        </Box>
        <Box style={{ padding: "15px 17px 24px" }}>
          <Skeleton w="40%" h={9} style={{ marginBottom: 9 }} />
          <Skeleton h={38} radius={8} />
        </Box>
      </Box>
    );
  }

  const archetypeById = (id: string) => archetypes.find((a) => a.id === id);

  if (sel.type === "node") {
    const pos = org.positions.find((p) => p.nodeId === sel.id);
    if (!pos) return <Box style={PANEL} />;
    const d = positionDisplay(pos, personas);
    const persona = pos.personaId ? personas.find((p) => p.id === pos.personaId) : undefined;
    const comms = org.relationships
      .filter((r) => r.from === pos.nodeId || r.to === pos.nodeId)
      .map((r) => {
        const counterpartId = r.from === pos.nodeId ? r.to : r.from;
        const counterpart = org.positions.find((p) => p.nodeId === counterpartId);
        const arch = archetypeById(r.archetype);
        return counterpart && arch ? { rel: r, counterpart, arch, counterpartName: positionDisplay(counterpart, personas).name } : null;
      })
      .filter((c): c is NonNullable<typeof c> => !!c);

    return (
      <Box style={PANEL}>
        <Box style={{ ...BLOCK, padding: "16px 17px 14px" }}>
          <Row gap={11} align="center">
            <IconBox size={40} radius={11} fontSize={18} color="#fff" background="var(--accent)">{d.glyph}</IconBox>
            <Box style={{ flex: 1, minWidth: 0 }}>
              <Text as="div" weight={600} size={16}>{d.name}</Text>
              <Row gap={7} align="center" style={{ marginTop: 3 }}>
                <Text size={10} tone="muted">{d.dept}</Text>
                {d.role && <Chip color="var(--accent)">{d.role}</Chip>}
              </Row>
            </Box>
          </Row>
        </Box>
        {pos.kind === "agent" ? (
          <Box style={BLOCK}>
            <SectionLabel style={{ marginBottom: 9 }}>Persona</SectionLabel>
            {persona ? (
              <Stack gap={6}>
                <Text as="div" size={12} weight={600}>{persona.name}</Text>
                {persona.blurb && <Text as="div" size={11} tone="muted" style={{ lineHeight: 1.5 }}>{persona.blurb}</Text>}
              </Stack>
            ) : (
              <Text size={11} tone="dim">No persona assigned.</Text>
            )}
          </Box>
        ) : (
          <Box style={BLOCK}>
            <SectionLabel style={{ marginBottom: 9 }}>{pos.kind === "resource" ? "Resource" : "External actor"}</SectionLabel>
            <Text size={12}>{pos.label ?? "Unnamed"}</Text>
          </Box>
        )}
        <Box style={{ padding: "15px 17px 24px" }}>
          <SectionLabel style={{ marginBottom: 9 }} right={<Text size={9} tone="dim">auto - from relationships</Text>}>Communication</SectionLabel>
          {comms.length === 0 ? (
            <Text size={11} tone="dim">No relationships yet - connect this position on the canvas.</Text>
          ) : (
            <Stack gap={7}>
              {comms.map((cm) => (
                <Box key={cm.rel.id} style={{ padding: "8px 9px", borderRadius: 8, background: "var(--bg-soft)", border: "1px solid var(--border-soft)" }}>
                  <Row gap={7} align="center">
                    <ColorSwatch color={`oklch(0.72 0.13 ${cm.arch.hue})`} size={7} radius={99} />
                    <Text size={12} weight={500}>{cm.arch.label} - {cm.counterpartName}</Text>
                  </Row>
                </Box>
              ))}
            </Stack>
          )}
        </Box>
        {onDeletePosition && (
          <Box style={{ padding: "0 17px 20px" }}>
            <ConfirmButton label="Delete position" armedLabel="Confirm - removes its links" onConfirm={() => onDeletePosition(pos.nodeId)} />
          </Box>
        )}
      </Box>
    );
  }

  const rel = org.relationships.find((r) => r.id === sel.id);
  if (!rel) return <Box style={PANEL} />;
  const arch = archetypeById(rel.archetype);
  const from = org.positions.find((p) => p.nodeId === rel.from);
  const to = org.positions.find((p) => p.nodeId === rel.to);
  const aLabel = from ? positionDisplay(from, personas).name : rel.from;
  const bLabel = to ? positionDisplay(to, personas).name : rel.to;
  const fwd = arch?.forward ?? [];
  const back = arch?.backward ?? [];

  return (
    <Box style={PANEL}>
      <Box style={{ ...BLOCK, padding: "16px 17px 15px" }}>
        <SectionLabel style={{ marginBottom: 9 }}>Relationship</SectionLabel>
        <Row gap={8} align="baseline">
          <Text as="span" weight={600} size={12.5}>{aLabel}</Text>
          <Text as="span" tone="dim">—</Text>
          <Text as="span" size={11} tone="muted">{arch?.label}</Text>
          <Text as="span" tone="dim">→</Text>
          <Text as="span" weight={600} size={12.5}>{bLabel}</Text>
        </Row>
        {arch?.blurb && <Text as="p" size={11} tone="muted" style={{ lineHeight: 1.45, margin: "11px 0 0" }}>{arch.blurb}</Text>}
      </Box>
      <Stack gap={10} style={{ padding: "15px 17px 24px" }}>
        <SectionLabel>Communication forms</SectionLabel>
        <FormLane from={aLabel} to={bLabel} forms={fwd} hue={arch?.hue ?? 0} />
        <FormLane from={bLabel} to={aLabel} forms={back} hue={arch?.hue ?? 0} />
      </Stack>
      {onDeleteRelationship && (
        <Box style={{ padding: "0 17px 20px" }}>
          <ConfirmButton label="Delete relationship" armedLabel="Confirm delete" onConfirm={() => onDeleteRelationship(rel.id)} />
        </Box>
      )}
    </Box>
  );
}

